function getActiveDamaGame(groupId) {
  const damaGame = dama.loadGame(groupId);
  if (damaGame && damaGame.status === 'playing') return { type: 'dama', game: damaGame };

  const damaStickerGame = damaSticker.loadGame(groupId);
  if (damaStickerGame && damaStickerGame.status === 'playing') return { type: 'damafig', game: damaStickerGame };

  return null;
}

function hasPendingDamaChallenge(groupId) {
  return !!(
    global.gameChallenges &&
    global.gameChallenges[groupId] &&
    ['dama', 'damafig'].includes(global.gameChallenges[groupId].gameType)
  );
}

function clearPendingDamaChallengeTimers(groupId) {
  if (!global.gameChallenges || !global.gameChallenges[groupId]) return;
  const challenge = global.gameChallenges[groupId];
  if (challenge.timeoutId) clearTimeout(challenge.timeoutId);
  if (challenge.warningTimeoutId) clearTimeout(challenge.warningTimeoutId);
  delete challenge.timeoutId;
  delete challenge.warningTimeoutId;
}

function clearPendingDamaChallenge(groupId) {
  clearPendingDamaChallengeTimers(groupId);
  if (!global.gameChallenges || !global.gameChallenges[groupId]) return;
  delete global.gameChallenges[groupId];
}

