const TEMP_DIR = path.join(__dirname, 'temp_videos');
const MAX_TEMP_SIZE_MB = 342; // Máximo 300MB na pasta temp
const MAX_VIDEO_AGE_MIN = 30; // Apagar vídeos com mais de 30 minutos

// Criar pasta temp se não existir
