// Função para gerenciar espaço automaticamente
function gerenciarEspacoTemp() {
  try {
    console.log('🔄 Gerenciando espaço temporário...');

    // 1. Apagar arquivos antigos primeiro
    const agora = Date.now();
    const files = fs.readdirSync(TEMP_DIR);

    let deletados = 0;
    let tamanhoLiberado = 0;

    files.forEach(file => {
      const filePath = path.join(TEMP_DIR, file);
      const stats = fs.statSync(filePath);
      const idadeMin = (agora - stats.mtimeMs) / (1000 * 60);

      if (idadeMin > MAX_VIDEO_AGE_MIN) {
        tamanhoLiberado += stats.size;
        fs.unlinkSync(filePath);
        deletados++;
        console.log(`🗑️ Apagado (antigo): ${file} (${Math.round(stats.size / 1024 / 1024)}MB)`);
      }
    });

    // 2. Se ainda estiver grande, apagar os mais velhos
    const tamanhoAtualMB = calcularTamanhoPastaMB(TEMP_DIR);

    if (tamanhoAtualMB > MAX_TEMP_SIZE_MB) {
      console.log(`⚠️ Pasta temp com ${tamanhoAtualMB}MB (limite: ${MAX_TEMP_SIZE_MB}MB)`);

      // Listar arquivos por idade
      const filesByAge = files
        .map(file => {
          const filePath = path.join(TEMP_DIR, file);
          return {
            name: file,
            path: filePath,
            age: fs.statSync(filePath).mtimeMs,
            size: fs.statSync(filePath).size
          };
        })
        .sort((a, b) => a.age - b.age); // Mais velhos primeiro

      // Apagar os mais antigos até ficar abaixo do limite
      for (const file of filesByAge) {
        if (tamanhoAtualMB <= MAX_TEMP_SIZE_MB) break;

        fs.unlinkSync(file.path);
        tamanhoAtualMB -= file.size / 1024 / 1024;
        tamanhoLiberado += file.size;
        deletados++;
        console.log(`🗑️ Apagado (por espaço): ${file.name}`);
      }
    }

    if (deletados > 0) {
      console.log(`✅ Liberados ${Math.round(tamanhoLiberado / 1024 / 1024)}MB, ${deletados} arquivos`);
    }

    // 3. Verificar espaço livre no sistema
    const espacoLivreMB = verificarEspacoLivreMB();
    console.log(`💾 Espaço livre no sistema: ${espacoLivreMB}MB`);

    return espacoLivreMB;

  } catch (error) {
    console.error('Erro ao gerenciar espaço temp:', error.message);
    return 0;
  }
}

function calcularTamanhoPastaMB(pasta) {
  if (!fs.existsSync(pasta)) return 0;

  let tamanhoTotal = 0;
  const files = fs.readdirSync(pasta);

  files.forEach(file => {
    const filePath = path.join(pasta, file);
    const stats = fs.statSync(filePath);
    if (stats.isFile()) {
      tamanhoTotal += stats.size;
    }
  });

  return Math.round(tamanhoTotal / 1024 / 1024);
}

function verificarEspacoLivreMB() {
  try {
    const output = execSync('df -m . | tail -1').toString();
    const parts = output.trim().split(/\s+/);
    const livre = parseInt(parts[3]); // Coluna do espaço livre em MB
    return livre;
  } catch (error) {
    console.error('Erro ao verificar espaço:', error.message);
    return 100; // Assume 100MB se não conseguir verificar
  }
}

async function enviarArquivoGrandeComoDocumento(from, caminhoArquivo, tamanhoMB) {
  console.log(`📦 Enviando arquivo grande (${tamanhoMB}MB) em chunks...`);

  // Verificar se arquivo existe
  if (!fs.existsSync(caminhoArquivo)) {
    throw new Error('Arquivo não encontrado');
  }

  // Se for menor que 50MB, envia normal
  if (tamanhoMB < 50) {
    const buffer = fs.readFileSync(caminhoArquivo);
    await corvo.sendMessage(from, {
      document: buffer,
      fileName: `Episodio_${tamanhoMB}MB.mp4`,
      mimetype: 'video/mp4',
      caption: `✅ Episódio (${tamanhoMB}MB)\n> © DARK DYABYNHO`
    });
    return;
  }

  // Para arquivos grandes (>50MB): estratégia alternativa
  // 1. Primeiro avisar
  await corvo.sendMessage(from, {
    text: `📦 *Arquivo muito grande (${tamanhoMB}MB)*\n\nPreparando envio seguro...`
  });

  // 2. Tentar enviar em modo document com streaming interno
  try {
    // Dependendo da biblioteca WhatsApp que você usa:
    // Opção A: Se for baileys/whatsapp-web.js
    const fileBuffer = fs.readFileSync(caminhoArquivo);

    await corvo.sendMessage(from, {
      document: fileBuffer,
      fileName: `Episodio_Anime_${tamanhoMB}MB.mp4`,
      mimetype: 'video/mp4',
      caption: `✅ Enviado! (${tamanhoMB}MB)\n> © DARK DYABYNHO`
    });

  } catch (error) {
    console.error("Erro no envio grande:", error.message);

    // 3. Último recurso: enviar link para download
    const nomeArquivo = path.basename(caminhoArquivo);
    await corvo.sendMessage(from, {
      text: `⚠️ *Não foi possível enviar o arquivo*\n\nArquivo muito grande: ${tamanhoMB}MB\n\n📌 *Soluções:*\n1. Use o link da API diretamente\n2. Baixe em partes\n3. Procure qualidade menor (480p)`
    });

    throw error;
  }
}

