// ---------- util ----------
function ensureRpgFiles() {
  try {
    if (!fs.existsSync(RPG_DIR)) fs.mkdirSync(RPG_DIR, { recursive: true });
    if (!fs.existsSync(RPG_PLAYERS)) fs.writeFileSync(RPG_PLAYERS, JSON.stringify({}, null, 2));
    if (!fs.existsSync(RPG_GUILDS)) fs.writeFileSync(RPG_GUILDS, JSON.stringify({}, null, 2));
  } catch (e) {
    console.log("[RPG] Erro criando arquivos:", e);
  }
}

function loadJSON(file, fallback = {}) {
  try {
    ensureRpgFiles();
    const raw = fs.readFileSync(file, "utf-8");
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch (e) {
    return fallback;
  }
}

function saveJSON(file, data) {
  try {
    ensureRpgFiles();
    const tmp = file + ".tmp";
    fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
    fs.renameSync(tmp, file);
    return true;
  } catch (e) {
    console.log("[RPG] Erro salvando JSON:", e);
    return false;
  }
}

function normJid(x) {
  // aceita string, array ou objeto
  if (!x) return null;
  if (typeof x === "string") return x;
  if (Array.isArray(x)) return x[0];
  return x?.jid || x?.id || null;
}

function jidToNum(jid) {
  if (!jid || typeof jid !== "string") return "";
  return jid.split("@")[0].replace(/\D/g, "");
}

function isRegistered(jid) {
  const players = loadJSON(RPG_PLAYERS, {});
  return !!players[jid];
}

function getPlayer(jid) {
  const players = loadJSON(RPG_PLAYERS, {});
  return players[jid] || null;
}

function setPlayer(jid, patch) {
  const players = loadJSON(RPG_PLAYERS, {});
  if (!players[jid]) return false;
  players[jid] = { ...players[jid], ...patch };
  return saveJSON(RPG_PLAYERS, players);
}

function addGold(jid, amount) {
  const p = getPlayer(jid);
  if (!p) return false;
  const v = Math.max(0, (p.ouro || 0) + Number(amount || 0));
  return setPlayer(jid, { ouro: v });
}

function addExp(jid, amount) {
  const p = getPlayer(jid);
  if (!p) return false;

  let exp = (p.exp || 0) + Number(amount || 0);
  let level = p.level || 1;

  // curva simples
  function needExp(lv) { return 80 + (lv * 40); }

  while (exp >= needExp(level)) {
    exp -= needExp(level);
    level += 1;

    // sobe atributos por level
    const up = {
      hpMax: (p.hpMax || 100) + 15,
      manaMax: (p.manaMax || 50) + 8,
      forca: (p.forca || 8) + 2,
      defesa: (p.defesa || 4) + 1,
      agilidade: (p.agilidade || 4) + 1,
      magia: (p.magia || 3) + 1,
    };
    p.hpMax = up.hpMax;
    p.manaMax = up.manaMax;
    p.forca = up.forca;
    p.defesa = up.defesa;
    p.agilidade = up.agilidade;
    p.magia = up.magia;
  }

  p.exp = exp;
  p.level = level;

  // cura parcial a cada level up
  p.hp = Math.min(p.hpMax, (p.hp || p.hpMax) + 30);
  p.mana = Math.min(p.manaMax, (p.mana || p.manaMax) + 15);

  const players = loadJSON(RPG_PLAYERS, {});
  players[jid] = p;
  return saveJSON(RPG_PLAYERS, players);
}

