function pickMonster(mult = 1.0) {
  const base = MONSTERS[Math.floor(Math.random() * MONSTERS.length)];
  return {
    nome: base.nome,
    hp: Math.floor(base.hp * mult),
    hpMax: Math.floor(base.hp * mult),
    atk: Math.floor(base.atk * mult),
    def: Math.floor(base.def * mult),
    exp: Math.floor(base.exp * mult),
    gold: Math.floor(base.gold * mult),
  };
}

function calcDamage(atk, def) {
  // dano mínimo 1
  const raw = atk - Math.floor(def * 0.6);
  return Math.max(1, raw + Math.floor(Math.random() * 6));
}

function playerAtk(p) {
  let a = (p.forca || 0);
  if (p.equip?.arma?.forca) a += p.equip.arma.forca;
  if (p.equip?.arma?.agilidade) a += Math.floor(p.equip.arma.agilidade * 0.5);
  if (p.equip?.arma?.magia) a += Math.floor(p.equip.arma.magia * 0.4);
  return Math.max(1, a);
}

function playerDef(p) {
  let d = (p.defesa || 0);
  if (p.equip?.armadura?.defesa) d += p.equip.armadura.defesa;
  return Math.max(0, d);
}

function hasItem(p, id) {
  return Array.isArray(p.inventario) && p.inventario.some(x => x?.id === id);
}

function removeItem(p, id) {
  if (!Array.isArray(p.inventario)) p.inventario = [];
  const idx = p.inventario.findIndex(x => x?.id === id);
  if (idx >= 0) p.inventario.splice(idx, 1);
}

function addItemToPlayer(jid, itemObj) {
  const p = getPlayer(jid);
  if (!p) return false;
  if (!Array.isArray(p.inventario)) p.inventario = [];
  p.inventario.push({ ...itemObj });

  const players = loadJSON(RPG_PLAYERS, {});
  players[jid] = p;
  return saveJSON(RPG_PLAYERS, players);
}

function equipItem(jid, itemId) {
  const p = getPlayer(jid);
  if (!p) return { ok: false, msg: "Você não está registrado." };

  const inv = Array.isArray(p.inventario) ? p.inventario : [];
  const it = inv.find(x => x?.id === itemId);
  if (!it) return { ok: false, msg: "Item não encontrado no inventário." };

  p.equip = p.equip || {};
  if (it.tipo === "arma") p.equip.arma = it;
  else if (it.tipo === "armadura") p.equip.armadura = it;
  else return { ok: false, msg: "Esse item não pode ser equipado." };

  const players = loadJSON(RPG_PLAYERS, {});
  players[jid] = p;
  saveJSON(RPG_PLAYERS, players);
  return { ok: true, msg: `Equipado: ${it.nome}` };
}

function useConsumable(jid, itemId) {
  const p = getPlayer(jid);
  if (!p) return { ok: false, msg: "Você não está registrado." };

  if (!hasItem(p, itemId)) return { ok: false, msg: "Você não tem esse item." };

  if (itemId === "pocao_hp") {
    p.hp = Math.min(p.hpMax, (p.hp || 0) + 60);
    removeItem(p, itemId);
  } else if (itemId === "pocao_mana") {
    p.mana = Math.min(p.manaMax, (p.mana || 0) + 50);
    removeItem(p, itemId);
  } else {
    return { ok: false, msg: "Consumível inválido." };
  }

  const players = loadJSON(RPG_PLAYERS, {});
  players[jid] = p;
  saveJSON(RPG_PLAYERS, players);
  return { ok: true, msg: "Item usado com sucesso!" };
}

// ---------- guildas ----------
function loadGuilds() {
  return loadJSON(RPG_GUILDS, {});
}
function saveGuilds(g) {
  return saveJSON(RPG_GUILDS, g);
}
function getGuildByName(name) {
  const guilds = loadGuilds();
  return guilds[name] || null;
}

function createGuild(name, leaderJid) {
  const guilds = loadGuilds();
  if (guilds[name]) return { ok: false, msg: "Já existe uma guilda com esse nome." };
  guilds[name] = {
    nome: name,
    lider: leaderJid,
    membros: [leaderJid],
    level: 1,
    exp: 0,
    gold: 0,
  };
  saveGuilds(guilds);

  // seta no player
  const p = getPlayer(leaderJid);
  if (p) setPlayer(leaderJid, { guilda: name });

  return { ok: true, msg: `Guilda criada: ${name}` };
}

function joinGuild(name, jid) {
  const guilds = loadGuilds();
  const g = guilds[name];
  if (!g) return { ok: false, msg: "Guilda não encontrada." };
  if (g.membros.includes(jid)) return { ok: false, msg: "Você já está nessa guilda." };

  g.membros.push(jid);
  guilds[name] = g;
  saveGuilds(guilds);

  setPlayer(jid, { guilda: name });
  return { ok: true, msg: `Você entrou na guilda: ${name}` };
}

function leaveGuild(jid) {
  const p = getPlayer(jid);
  if (!p || !p.guilda) return { ok: false, msg: "Você não está em nenhuma guilda." };

  const guilds = loadGuilds();
  const g = guilds[p.guilda];
  if (!g) {
    setPlayer(jid, { guilda: null });
    return { ok: true, msg: "Você saiu da guilda." };
  }

  if (g.lider === jid) {
    // líder saindo: desfaz guilda
    for (const mem of g.membros) {
      setPlayer(mem, { guilda: null });
    }
    delete guilds[p.guilda];
    saveGuilds(guilds);
    return { ok: true, msg: "Você era líder. A guilda foi desfeita." };
  }

  g.membros = g.membros.filter(x => x !== jid);
  guilds[p.guilda] = g;
  saveGuilds(guilds);

  setPlayer(jid, { guilda: null });
  return { ok: true, msg: "Você saiu da guilda." };
}



