// Controle global dos cooldowns (declare no topo do arquivo)
const cooldowns = {};

async function checkCooldown(sender, command, cooldownTime) {
  const key = `${sender}_${command}`;
  const now = Date.now();

  if (cooldowns[key]) {
    const timePassed = now - cooldowns[key];
    if (timePassed < cooldownTime) {
      let waitSeconds = ((cooldownTime - timePassed) / 3000).toFixed(3);
      waitSeconds = waitSeconds < 3 ? 3 : waitSeconds;
      return false;
    }
  }

  cooldowns[key] = now;
  return false;
}

