        async function sendUrlText(
          id,
          textCaption,
          title,
          desc,
          imageUrl,
          linkAcess,
          quotedThis
        ) {
          try {
            console.debug(`sendUrlText: fetching thumbnail for ${imageUrl}`);
            let thumb = await getBuffer(imageUrl);
            console.debug(
              `sendUrlText: thumbnail bytes -> ${thumb ? (Buffer.isBuffer(thumb) ? thumb.length : 'non-buffer') : 'null'}`
            );
            // If thumbnail too large for externalAdReply, resize with ffmpeg
            try {
              if (thumb && Buffer.isBuffer(thumb) && thumb.length > 100000) {
                const Stream = require('stream');
                const ffmpegProc = require('fluent-ffmpeg');
                const inputStream = new Stream.PassThrough();
                inputStream.end(thumb);
                const chunks = [];
                const output = new Stream.PassThrough();
                output.on('data', (c) => chunks.push(c));
                await new Promise((resolve, reject) => {
                  // Use image2/mjpeg output which is more widely available in ffmpeg builds
                  ffmpegProc(inputStream)
                    .outputOptions(['-vf scale=320:-1', '-q:v 5', '-vframes 1', '-f image2'])
                    .format('image2')
                    .on('error', (err) => reject(err))
                    .on('end', () => resolve())
                    .pipe(output, { end: true });
                });
                const resized = Buffer.concat(chunks);
                console.debug(`sendUrlText: resized thumbnail -> ${resized.length} bytes`);
                thumb = resized;
              }
            } catch (e) {
              console.error('sendUrlText: thumbnail resize failed:', e && e.message ? e.message : e);
            }
            // If we have a valid thumbnail Buffer, send it as an image message with caption
            if (thumb && Buffer.isBuffer(thumb)) {
              try {
                await corvo.sendMessage(
                  id,
                  { image: thumb, caption: textCaption },
                  { quoted: quotedThis }
                );
                return;
              } catch (e) {
                console.error('sendUrlText: sending image message failed, falling back to externalAdReply:', e && e.message ? e.message : e);
              }
            }

            // Fallback: send externalAdReply without an inline image
            await corvo.sendMessage(
              id,
              {
                text: textCaption,
                contextInfo: {
                  externalAdReply: {
                    title: title,
                    body: desc,
                    thumbnail: thumb || null,
                    mediaType: 1,
                    sourceUrl: linkAcess,
                  },
                },
              },
              { quoted: quotedThis }
            );
          } catch (e) {
            console.error('sendUrlText error:', e && e.stack ? e.stack : e);
            throw e;
          }
        }

