        // 🔒 SEGURANÇA: o eval de código (`?codigo`) é EXCLUSIVO do DONO.
        // Sem este gate, QUALQUER pessoa do grupo poderia mandar `?process.exit()`
        // ou `?fs.rmSync(...)` e executar código arbitrário no PC do dono (RCE).
        // Não-dono → a mensagem segue o fluxo normal (pergunta comum, sem reply
        // de erro e sem console.error).
        // 🎯 Gate ESTRITO de dono (não usa SoDono): SoDono inclui as listas
        // nit/supre/chyt — essas pessoas NÃO devem ganhar poder de eval (RCE).
        // Só o dono: numerodono (número configurado) OU DonoOficial (cobre o
        // @lid, comum em grupo onde o remetente pode vir como LID).
        if (body.startsWith("?") && (numerodono.includes(sender) || DonoOficial)) {
          const JurandirCode = body.trim().substring(1);

          if (!JurandirCode.trim()) {
            return reply("Código inválido. Use ? seguido de uma expressão JavaScript válida.");
          }

          // 🐛 FIX 2026-08-10: só entra no eval se o texto PAREÇA código JS de
          // verdade — tem sintaxe (parênteses/chaves/operadores) OU não tem
          // espaços. Mensagem comum começando com "?" (ex: "? o que é isso",
          // "?tem como?", "??") virava `const res = o que é isso;` → estourava
          // "SyntaxError: Unexpected token '?'" no chat e poluía o console.
          // Pergunta em texto normal agora NÃO é avaliada: segue o fluxo normal.
          const codeTrim = JurandirCode.trim();
          const pareceCodigo =
            codeTrim.length > 0 &&
            codeTrim.replace(/\?/g, "").trim().length > 0 && // não é só interrogação
            (/[(){}[\]=\-+*/%<>!&|^~]/.test(codeTrim) || !/\s/.test(codeTrim));

          if (pareceCodigo) {
            try {
              // evita tokens claramente inválidos como @#
              if (/[@#]/.test(JurandirCode)) {
                throw new SyntaxError("Código contém caracteres inválidos para execução.");
              }

            const resultadoexec = await eval(`(async () => { 
const res = ${JurandirCode};
return (res instanceof Promise) ? await res : res;
})()`);

            if (resultadoexec !== undefined) {
              const util = require("util");

              const saida = util.inspect(resultadoexec, {
                depth: null,
                showHidden: true,
                colors: false,
                getters: true,
              });
              await reply("```" + saida + "```");
            }            } catch (e) {
              console.error("Erro ao avaliar código:", e);
              return reply(`Erro ao processar o código: ${e.message}`);
            }
          }
        }


