            const chapterId = args[0];
            reagir(from, "📚");

            // Criar pasta temporária se não existir
            const fs = require('fs');
            const path = require('path');
            const tempDir = path.join(__dirname, 'temp');

            if (!fs.existsSync(tempDir)) {
              fs.mkdirSync(tempDir, { recursive: true });
            }

            // Limpar pasta temp antes de começar (opcional, mas útil)
            try {
              const files = fs.readdirSync(tempDir);
              files.forEach(file => {
                const filepath = path.join(tempDir, file);
                if (fs.statSync(filepath).isFile()) {
                  fs.unlinkSync(filepath);
                }
              });
            } catch (e) {
              // Ignora erros na limpeza inicial
            }

            const res = await axios.get(
              `https://api.mangadex.org/at-home/server/${chapterId}`,
              {
                headers: {
                  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
                }
              }
            );

            const { baseUrl, chapter: ch } = res.data;
            const { hash, data } = ch;

            // Validar array de dados
            if (!Array.isArray(data) || data.length === 0) {
              return reply("❌ Nenhuma página encontrada para este capítulo.");
            }

            reply(`📖 Baixando ${data.length} páginas...\n⏳ Por favor aguarde...`);

            // Função melhorada para baixar imagem
            const downloadImage = async (url, filepath) => {
              const response = await axios({
                url,
                method: 'GET',
                responseType: 'stream',
                headers: {
                  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
                  'Accept': 'image/webp,image/apng,image/*,*/*'
                },
                timeout: 30000 // 30 segundos de timeout
              });

              return new Promise((resolve, reject) => {
                const writer = fs.createWriteStream(filepath);

                response.data.on('error', reject);
                writer.on('error', reject);
                writer.on('finish', () => {
                  // Pequeno delay para garantir que o arquivo foi escrito
                  setTimeout(resolve, 100);
                });

                response.data.pipe(writer);
              });
            };

            // Baixar todas as páginas primeiro, em ordem e com delays
            const downloadedFiles = [];
            const limit = Math.min(data.length, 30); // Limite de 30 páginas por vez

            reply(`📥 Baixando ${limit} páginas (de ${data.length})...`);

            for (let i = 0; i < limit; i++) {
              try {
                console.log(`📥 Baixando página ${i + 1}/${limit}`);

                const url = `${baseUrl}/data/${hash}/${data[i]}`;
                const ext = path.extname(data[i]) || '.jpg';
                const filename = `page_${i.toString().padStart(3, '0')}_${chapterId}${ext}`;
                const filepath = path.join(tempDir, filename);

                // Tentar baixar com retry
                let retries = 3;
                while (retries > 0) {
                  try {
                    await downloadImage(url, filepath);

                    // Verificar se o arquivo existe e tem tamanho
                    await new Promise(resolve => setTimeout(resolve, 200)); // Aguardar escrita
                    if (fs.existsSync(filepath) && fs.statSync(filepath).size > 1024) {
                      downloadedFiles.push({
                        index: i,
                        filepath: filepath,
                        filename: filename
                      });
                      console.log(`✅ Página ${i + 1} baixada: ${filepath}`);
                      break; // Sucesso, sai do loop de retry
                    } else {
                      throw new Error('Arquivo muito pequeno ou vazio');
                    }
                  } catch (downloadError) {
                    retries--;
                    if (retries === 0) {
                      console.error(`❌ Falha ao baixar página ${i + 1}:`, downloadError.message);
                      // Adicionar arquivo vazio para manter a ordem
                      downloadedFiles.push({
                        index: i,
                        filepath: null,
                        filename: `erro_${i}`
                      });
                    } else {
                      console.log(`🔄 Retentando página ${i + 1} (${3 - retries}/3)`);
                      await new Promise(resolve => setTimeout(resolve, 2000)); // Aguardar 2s antes de retry
                    }
                  }
                }

                // Delay entre downloads para não sobrecarregar
                if (i < limit - 1) { // Não esperar após o último
                  await new Promise(resolve => setTimeout(resolve, 500));
                }

              } catch (pageError) {
                console.error(`Erro crítico na página ${i + 1}:`, pageError.message);
                downloadedFiles.push({
                  index: i,
                  filepath: null,
                  filename: `erro_${i}`
                });
              }
            }

            console.log(`✅ Download concluído: ${downloadedFiles.filter(f => f.filepath).length}/${limit} páginas baixadas`);

            // Ordenar arquivos por índice antes de enviar
            downloadedFiles.sort((a, b) => a.index - b.index);

            // Agora enviar as páginas em ordem
            reply(`📤 Enviando ${downloadedFiles.filter(f => f.filepath).length} páginas...`);

            let sentCount = 0;
            for (let i = 0; i < downloadedFiles.length; i++) {
              const fileInfo = downloadedFiles[i];

              try {
                if (fileInfo.filepath && fs.existsSync(fileInfo.filepath)) {
                  console.log(`📤 Enviando página ${i + 1}/${downloadedFiles.length}`);

                  await corvo.sendMessage(from, {
                    image: fs.readFileSync(fileInfo.filepath),
                    caption: `📖 Página ${i + 1}/${data.length}`
                  });

                  sentCount++;

                  // Apagar arquivo após enviar
                  try {
                    fs.unlinkSync(fileInfo.filepath);
                    console.log(`🗑️ Arquivo ${fileInfo.filename} apagado`);
                  } catch (deleteError) {
                    console.warn(`⚠️ Não foi possível apagar ${fileInfo.filepath}:`, deleteError.message);
                  }

                  // Delay entre envios
                  if (i % 3 === 0 && i > 0) { // A cada 3 mensagens
                    await new Promise(resolve => setTimeout(resolve, 1500));
                  }
                } else {
                  console.log(`⏭️ Pulando página ${i + 1} (erro no download)`);
                  // Pode enviar uma mensagem informando que a página pulou
                  if (i === 0 || i === downloadedFiles.length - 1) {
                    await corvo.sendMessage(from, {
                      text: `⚠️ Página ${i + 1} não pôde ser carregada`
                    });
                  }
                }
              } catch (sendError) {
                console.error(`❌ Erro ao enviar página ${i + 1}:`, sendError.message);
                // Continuar com as próximas páginas
              }
            }

            console.log(`✅ Envio concluído: ${sentCount} páginas enviadas`);

