            const pdfDir = path.join(tempDir, `pdf_${chapterId}`);
            if (!fs.existsSync(pdfDir)) {
              fs.mkdirSync(pdfDir, { recursive: true });
            }

            // Baixar imagens SILENCIOSAMENTE
            const imagePaths = [];
            for (let i = 0; i < data.length; i++) {
              try {
                const imageUrl = `${baseUrl}/data/${hash}/${data[i]}`;
                const imagePath = path.join(pdfDir, `page_${i + 1}.jpg`);

                const response = await axios({
                  method: 'GET',
                  url: imageUrl,
                  responseType: 'stream'
                });

                const writer = fs.createWriteStream(imagePath);
                response.data.pipe(writer);

                await new Promise((resolve, reject) => {
                  writer.on('finish', resolve);
                  writer.on('error', reject);
                });

                imagePaths.push(imagePath);

                // SEM ATUALIZAÇÕES DE PROGRESSO

              } catch (error) {
                console.error(`Erro ao baixar página ${i + 1}:`, error);
              }
            }

            // Criar PDF SILENCIOSAMENTE
            const pdfPath = path.join(tempDir, `manga_${chapterId}_${Date.now()}.pdf`);
            const doc = new PDFDocument({
              size: 'A4',
              margin: 0,
              info: {
                Title: `Mangá - Capítulo ${chapterId}`,
                Author: 'MangaBot',
                CreationDate: new Date()
              }
            });

            // Pipe do PDF para arquivo
            const stream = fs.createWriteStream(pdfPath);
            doc.pipe(stream);

            // Adicionar imagens ao PDF SILENCIOSAMENTE
            if (imagePaths.length > 0) {
              for (let i = 0; i < imagePaths.length; i++) {
                try {
                  // Adicionar nova página
                  if (i > 0) doc.addPage();

                  // Centralizar imagem na página
                  const img = doc.openImage(imagePaths[i]);
                  const imgWidth = img.width;
                  const imgHeight = img.height;
                  const pageWidth = doc.page.width;
                  const pageHeight = doc.page.height;

                  // Calcular dimensões para caber na página
                  const ratio = Math.min(pageWidth / imgWidth, pageHeight / imgHeight);
                  const width = imgWidth * ratio;
                  const height = imgHeight * ratio;
                  const x = (pageWidth - width) / 2;
                  const y = (pageHeight - height) / 2;

                  doc.image(img, x, y, { width, height });

                  // Adicionar número da página no rodapé
                  doc.fontSize(10)
                    .fillColor('#666666')
                    .text(`Página ${i + 1}`, 20, pageHeight - 30, {
                      align: 'center',
                      width: pageWidth - 40
                    });

                } catch (error) {
                  console.error(`Erro ao adicionar página ${i + 1} ao PDF:`, error);
                }
              }
            }

            // Finalizar PDF
            doc.end();

            // Esperar o stream terminar
            await new Promise((resolve, reject) => {
              stream.on('finish', resolve);
              stream.on('error', reject);
            });

            // Obter informações do arquivo
