            const cheerio = require("cheerio");
            const FormData = require("form-data");
            const moment = require("moment-timezone");
            async function tiktokV1(url) {
              const params = new URLSearchParams();
              params.set("url", url);
              params.set("hd", "1");
              const { data } = await axios.post(
                "https://tikwm.com/api/",
                params,
                {
                  headers: {
                    "Content-Type":
                      "application/x-www-form-urlencoded; charset=UTF-8",
                    Cookie: "current_language=en",
                    "User-Agent":
                      "Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Mobile Safari/537.36",
                  },
                }
              );
              return data;
            }
            async function tiktokV2(url) {
              const form = new FormData();
              form.append("q", url);
              const { data } = await axios.post(
                "https://savetik.co/api/ajaxSearch",
                form,
                {
                  headers: {
                    ...form.getHeaders(),
                    Accept: "*/*",
                    Origin: "https://savetik.co",
                    Referer: "https://savetik.co/en2",
                    "User-Agent":
                      "Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/137.0.0.0 Mobile Safari/537.36",
                    "X-Requested-With": "XMLHttpRequest",
                  },
                }
              );
              const $ = cheerio.load(data.data); //𖦜 𝐀𝐋𝐀𝐍𝐀 𝐃𝐄𝐒𝐈𝐆𝐍 𝐎𝐅𝐈𝐂𝐈𝐀𝐋 𖦜⁩
              const title = $(".thumbnail .content h3").text().trim();
              const thumbnail = $(".thumbnail .image-tik img").attr("src");
              const video_url = $("video#vid").attr("data-src");
              const slide_images = [];
              $(".photo-list .download-box li").each((_, el) => {
                const img = $(el)
                  .find(".download-items__thumb img")
                  .attr("src");
                if (img) slide_images.push(img);
              });
              return { title, thumbnail, video_url, slide_images };
            }
