                enviarPv: async (numero, texto) => {
                  const n = String(numero || "").trim();
                  const digitos = n.replace(/\D/g, "");
                  if (!digitos) return { erro: "Número inválido." };
                  const jid = n.includes("@") ? n : `${digitos}@s.whatsapp.net`;
                  await corvo.sendMessage(jid, { text: String(texto || "") });
                  return { ok: true, jid };
                },
                // 🔎 Resolve o NÚMERO de um membro do grupo pelo NOME (ex: "fulano").
                // Retorna o número (sem @) ou null se não achar. Em PV, retorna null.
                resolverMembro: async (nome) => {
                  try {
                    if (!isGroup) return null;
                    const meta = await corvo.groupMetadata(from);
                    const alvo = String(nome || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
                    if (!alvo) return null;
                    const limpa = (s) => String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
                    const comNome = (meta?.participants || [])
                      .map((p) => ({ p, nome: limpa(p.name || p.pushname || "") }))
                      .filter((x) => x.nome);
                    // 1) nome EXATO primeiro (evita "a" achar "Ana" errada)
                    let parte = comNome.find((x) => x.nome === alvo)?.p;
                    // 2) senão, substring só com nome razoavelmente longo (>=3)
                    if (!parte && alvo.length >= 3) {
                      parte = comNome.find((x) => x.nome.includes(alvo))?.p;
                    }
                    if (!parte) return null;
                    return String(parte.jid || parte.id || "").split("@")[0] || null;
                  } catch (e) { return null; }
                },
